#****End: Generated Statements****

##################################################################################################
#Region - Cleanup

IF( sDatabaseParameterType @<> 'object' % pConnectionName @= '' );
  ExecuteProcess( '}bedrock.process.execute_http_request', 'pMethod', 'POST', 'pURL', sURL | '/ActiveSession/tm1.Close' );
ENDIF;

